import debugm from 'debug';
const debug = debugm('zoodb._zoodbloaderhandler');

import loMerge from 'lodash/merge.js';

/**
 * This class takes care of loading raw database data using a `dbdataloader`
 * (e.g. :class:`YamlDbDataLoader`) into a :class:`ZooDb` instance.  It can take
 * care of performing reloads, etc.
 *
 * You can install a `ZooDbDataLoaderHandler` in a :class:`ZooDb` instance by
 * calling :meth:`ZooDb.install_zoo_loader_handler()`.
 * 
 * This class will delegate loading the zoo database data
 * to one or more database loader instances provided
 * to the `db_data_loaders` argument.  The `db_data_loaders` argument can be
 * a single loader instance or an array of such instances.  Loader objects
 * can be, for example, :js:class:`YamlDbDataLoader` or
 * :js:class:`FlmFilesDbDataLoader` instances.
 * 
 * If you specify an array of loaders, data will be loaded from each of the
 * loader objects in sequence, and all the loaded objects will be included
 * in the loaded data.  Loaders are invoked in the order they appear in the
 * array.  You are responsible for making sure loaders later in the array
 * do not overwrite data loaded by earlier ones, for instance, by ensuring
 * that each loader loads objects of different types.
 *
 * The reason for splitting off the logic of the loader handler is to avoid
 * bloating the `ZooDb` class definition, especially in case a user would like
 * to create a barebones `ZooDb`, e.g. with hard-coded JSON data, without
 * reloading features, in which case neither a loader nor a loader handler
 * is necessary.
 *
 * This class will do a few more things other than directly calling the
 * `dbdataloader`'s load method and setting the data on the `zoodb` instance:
 *
 * - Checks if a loading operation is already currently in progress, and if
 *   so, declines to reload the data with an error message in the console.
 *
 * - Calls the `zoodb` instance's `validate()` method, to ensure that the loaded
 *   data conforms to any validation checks.
 *
 * - Provides a `load()` function that can be called repeatedly --- the method
 *   performs an initial zoo load the first time it is called and then performs
 *   reload operations on subsequent calls.
 *
 * Constructor arguments:
 *
 * - `db_data_loaders` - one or more `dbdataloader` instance to use for loading
 *   the database data. You might include, for instance, a
 *   :class:`YamlDbDataLoader` instance.  Specify either an array of loader
 *   instances or a single loader instance.
 * 
 * - `options` - [optional] an object with the following properties.
 *
 * Options:
 *
 * - ``throw_reload_errors`` (default: ``true``) - when `true`, reload
 *   operation failures cause an error to be thrown (regardless of whether
 *   they are initiated with a second call to `load()` or with a call to
 *   `reload()`).  When `false`, reload errors are logged to the console
 *   and the function returns normally.  Setting this to `false` is useful
 *   in development mode with Eleventy, where you do not want to stop the
 *   development server by throwing an exception when reloading a database
 *   after a file modification is detected.
 *
 */
export class ZooDbDataLoaderHandler
{
    constructor(db_data_loaders, options={})
    {
        this.options = loMerge(
            {
                throw_reload_errors: true
            },
            options,
        );

        this.db_data_loaders =
            Array.isArray(db_data_loaders) ? db_data_loaders: [ db_data_loaders ];

        this.zoodb = null;

        this._currently_loading = null;
        this._first_load_done = null;
    }

    /**
     * Initializes the loader handler, giving it the zoodb instance.
     *
     * **Normally, you don't need to call this method!** This function is
     * automatically called by the :class:`ZooDb` instance when you call
     * :meth:`ZooDb.install_zoo_loader_handler()`.
     */
    async initialize(zoodb)
    {
        this.zoodb = zoodb;

        this._currently_loading = false;
        this._first_load_done = false;
    }

    /**
     * Load the data into the zoo, using the dbdataloader.  See the class
     * documentation for details.
     *
     * After the initial call to load(), any subsequent calls to load() will
     * automatically reload the zoo in the same way as directly calling
     * reload().
     */
    async load()
    {
        if (this._currently_loading) {
            console.error("The zoo is already currently being loaded! Please wait "
                          + "before trying to reload the zoo.");
            return;
        }

        if (this._first_load_done) {
            return await this.reload();
        }

        debug(`Initiating loading the zoo data using our registered data db_data_loader`);

        this._currently_loading = true;

        try {

            //
            // Load the data files
            //
            let dbdata = { schemas: {}, objects: {}, };
            let newdbdata;
            for (const db_data_loader of this.db_data_loaders) {

                newdbdata = await db_data_loader.load({ schemas: this.zoodb.schemas });

                for (const [k,v] of Object.entries(newdbdata.schemas ?? {})) {
                    if (dbdata.schemas[k] != null) {
                        throw new Error(
                            `Conflict: same schema name ‘${k}’ loaded by different db data loaders!`
                        );
                    }
                    dbdata.schemas[k] = v;
                }

                for (const [object_type, object_db] of Object.entries(newdbdata.objects ?? {})) {
                    dbdata.objects[object_type] ??= {};
                    for (const [k,v] of Object.entries(object_db)) {
                        if (dbdata.objects[object_type][k] != null) {
                            throw new Error(
                                `Conflict: same object ID ‘${k}’ loaded by different `
                                + `db data loaders!`
                            );
                        }
                        dbdata.objects[object_type][k] = v;
                    }
                }

            }

            //
            // Load the zoo from the data files
            //
            await this.zoodb.load_data( dbdata );

        } finally {
            this._currently_loading = false;
        }

        this._first_load_done = true;

        debug("Validating Zoo ...");

        //
        // & validate its contents
        //
        await this.zoodb.validate();

        debug("Zoo is now loaded!");
    }

    /**
     * Reload data into the zoo using the dbdataloader.  You must have called
     * load() at least once before, and that call must have completed.
     *
     * Usually you don't need to call reload() directly and simply call load()
     * instead.  After the initial call to load(), any subsequent calls to
     * load() will automatically reload the zoo in the same way as directly
     * calling reload().
     */
    async reload()
    {
        if (this._currently_loading) {
            console.error("The zoo is already currently being loaded! Will not "
                          + "reload again at this time.");
            return;
        }
        if (!this._first_load_done) {
            throw new Error(
                `Call to ZooDbDataLoaderHandler.reload() before having called load().  You `
                + `can only call reload() after having loaded the zoo earlier with load(). `
                + `if in doubt, simply call load() which will automatically perform a reload `
                + `operation if it detects the zoo was already loaded once.`
            );
        }

        this._currently_loading = true;

        try {

            debug("Reloading Zoo!");

            let reloaded_objects = {};

            for (const db_data_loader of this.db_data_loaders) {
                const reload_result = await db_data_loader.reload(
                    this.zoodb.db,
                    { schemas: this.zoodb.schemas }
                );
                let this_reloaded_objects = reload_result.reload_info?.reloaded_objects ?? {};
                for (const [object_type, object_db] of Object.entries(this_reloaded_objects)) {
                    reloaded_objects[object_type] ??= {};
                    for (const [k,v] of Object.entries(object_db)) {
                        if (reloaded_objects[object_type][k] != null) {
                            throw new Error(
                                `Conflict: same object ID ‘${k}’ loaded by two loaders!`
                            );
                        }
                        reloaded_objects[object_type][k] = v;
                    }
                }
            }

            await this.zoodb.update_objects(reloaded_objects);

            debug("Re-Validating Zoo");

            await this.zoodb.validate();

            debug("Finished reloading Zoo.");

            return true;

        } catch (err) {
            console.error('ERROR RELOADING DATA: ', err);
            if (this.options.throw_reload_errors ?? false) {
                throw err;
            }
        } finally {
            this._currently_loading = false;
        }
    }

}
